/* Vesper road sites (void-runner/vesper-sites.js, vesper-sites-data.js generated by tools/assets/vesper/build_vesper_village.py; docs/development/VESPER_ROAD.md):
   the village's collision, walking area, pad, places and doors. Pure: no browser. */
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const S=require('../void-runner/vesper-sites.js'),W=require('../void-runner/vesper-world.js'),{road:R}=require('../void-runner/vesper.js'),O=require('../void-runner/opening-data.js'),X=require('../void-runner/exploration-controller.js'),P=require('../void-runner/places.js');
const L=O.layout(),village=S.sites().find(s=>s.id==='village');

test('the village is generated with its model: collision boxes, lamps with physical sources, and the bar and store as places',()=>{
 assert(village,'village');assert(village.solids.length>=40);assert(village.lamps.length>=5);assert.deepEqual(village.places.map(p=>p.id).sort(),['vesper-bar','vesper-store']);
 const b=fs.readFileSync(path.join(__dirname,'..','void-runner',village.model));assert.equal(b.toString('latin1',0,4),'glTF');assert(b.length<4e6,'the village model stays modest');
 for(const s of village.solids)assert(s.size.every(v=>v>0),s.id);
 // the yard's own layout is unchanged: its 16 solids come first
 assert.deepEqual(L.solids.slice(0,16).map(s=>s.id),['back-wall','left-wall','right-wall','left-bench','right-storage','holo-case','kestrel','target-rack','range-backstop','fuel-tank','habitat-east','habitat-north','habitat-west','habitat-ridge','frontier-supply','dust-bar']);
 assert.equal(L.solids.length,16+S.solids().length);
});

test('nothing solid stands on the road or its shoulders through the village; the street is flat',()=>{
 for(const p of R.centreline().filter(p=>S.inRect(village.area,p.x,p.z)))for(const o of [-5.1,-3.5,0,3.5,5.1]){const x=p.x-p.tz*o,z=p.z+p.tx*o;
  for(const s of village.solids)assert(!(Math.abs(x-s.position[0])<s.size[0]/2&&Math.abs(z-s.position[2])<s.size[2]/2),s.id+' on the road');}
 const pad=village.pad;for(let x=pad[0];x<=pad[1];x+=6)for(let z=pad[2];z<=pad[3];z+=6){const h=W.height(x,z);assert(Math.abs(h-(village.y-W.FLOOR))<.8,'pad flat at '+x+','+z+' ('+h.toFixed(2)+')');}
});

test('walking: the bar and the store are entered through their doors; walls and houses block; the village yard is walkable, the hills beyond are not',()=>{
 for(const id of ['vesper-bar','vesper-store']){const q=village.places.find(p=>p.id===id),w={x:q.approach[0],z:q.approach[1],yaw:q.yaw,pitch:0};
  for(let i=0;i<160;i++)X.step(w,{x:0,z:1},.05,L);assert(S.inRect(q.rect,w.x,w.z),id+' entered: '+w.x.toFixed(1)+','+w.z.toFixed(1));
  // inside: a point well within the room is free
  assert(!X.blocked(q.inside[0],q.inside[1],L),id+' inside point free');}
 const [ox,oz]=village.origin;
 const w={x:ox+6,z:oz+18,yaw:-Math.PI/2,pitch:0};for(let i=0;i<80;i++)X.step(w,{x:0,z:1},.05,L);assert(w.x>ox+4,'the bar\'s east wall stops a walker outside it');
 for(const s of village.solids.filter(s=>/house-\d$/.test(s.id)))assert(X.blocked(s.position[0],s.position[2],L),s.id);
 assert(!X.blocked(ox-50,oz-28,L),'the village yard');assert(X.blocked(ox,oz+60,L)&&X.blocked(ox,oz-60,L),'beyond the village');
});

test('places: the village, the bar and the store are registered under the road with approach points on the ground; PROPOSED names',()=>{
 for(const id of ['vesper-village','vesper-bar','vesper-store']){const n=P.node(id);assert(n&&n.proposed,id);assert.equal(n.scene,'vesper');const t=P.target(id);
  assert(Math.abs(t[1]-(R.groundAt(t[0],t[2])+1.7))<.15,id+' approach height');assert(!X.blocked(t[0],t[2],L),id+' approach free');}
 assert.equal(P.deepest({scene:'vesper',...(([x,z])=>({x,z}))(village.places[0].inside)}),village.places[0].id);
});

test('the truck drives through the village on the road and is stopped by a building',()=>{
 const VR=require('../void-runner/vehicle-rules.js'),world={solids:L.solids,bounds:L.bounds,inBounds:require('../void-runner/vesper.js').vehicleBounds,groundHeight:R.groundAt};
 for(const p of R.centreline().filter(p=>S.inRect(village.area,p.x,p.z)))assert(!VR.collides(p.x,p.z,Math.atan2(p.tx,p.tz),world),'blocked at s='+p.s.toFixed(0));
 const bar=village.solids.find(s=>s.id==='vesper-village-bar-e-0');assert(VR.collides(bar.position[0],bar.position[2],0,world));
});
